/** The browser verifier gives the server's verdict on every "try to fool the verifier" case.
 *
 * Run: node --experimental-strip-types --test apps/web/tests/
 * The cases and the server's verdicts are generated by scripts/export_demo_data.py.
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { expandLog, verifyClaim } from '../src/studio/verifier.ts';

const here = dirname(fileURLToPath(import.meta.url));
const read = (path) => JSON.parse(readFileSync(join(here, path), 'utf8'));
const cases = read('verifier-benchmark-cases.json');
const summary = read('../src/studio/generated/verifier-benchmark.json');
const exportData = read('../src/studio/generated/nbr-riv.json');
const log = expandLog(read('../src/studio/generated/nbr-riv-events.json')).filter((e) => e.match_clock_ms < exportData.replay_end_ms);
const evidence = { match_id: exportData.match_id, event_ids: log.map((e) => e.event_id), window: { from_ms: 0, to_ms: exportData.replay_end_ms } };

test('the browser verifier agrees with the server on every benchmark case', () => {
  assert.ok(cases.length >= 1000, `only ${cases.length} cases`);
  const disagreements = [];
  for (const item of cases) {
    const result = verifyClaim(item.claim, evidence, log, exportData.display_names);
    if (result.status !== item.status || result.query_id !== item.query_id) {
      disagreements.push(`${item.name}: ${result.status}/${result.query_id} vs ${item.status}/${item.query_id}`);
    }
  }
  assert.deepEqual(disagreements, []);
});

test('the published results match the cases', () => {
  const total = summary.false.total + summary.true.total;
  assert.equal(total, cases.length);
  assert.equal(summary.false.caught, summary.false.total);
  assert.equal(summary.true.wrongly_rejected, 0);
});
